  };

  const withIdentifier = async (
    identifier: string,
    overrides: Partial<Sender> = {}
  ): Promise<Sender> =>
    defaultSender({
      identifier,
      name: overrides.name ?? `Sender ${identifier}`,
      ...overrides
    });

  return {
    default: defaultSender,
    withIdentifier
  };
};
